package dev.minegame.mines;
import org.bukkit.command.*;import org.bukkit.entity.Player;
public final class FightsAdminCommand implements CommandExecutor {private final FightsManager fights;public FightsAdminCommand(FightsManager fights){this.fights=fights;}public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage("Only players can use this command.");return true;}if(!fights.isAdmin(p)){p.sendMessage(fights.colorize("&cNo permission."));return true;}if(a.length==0){help(p);return true;}try{switch(a[0].toLowerCase()){case "create"->fights.create(p,a.length>1?Integer.parseInt(a[1]):9,a.length>2?Integer.parseInt(a[2]):2);case "fighters"->fights.setFighterCount(p,Integer.parseInt(a[1]),Integer.parseInt(a[2]));case "remove"->fights.remove(p,Integer.parseInt(a[1]));case "move"->{if(a.length>=5)fights.move(p,Integer.parseInt(a[1]),Integer.parseInt(a[2]),Integer.parseInt(a[3]),Integer.parseInt(a[4]));else fights.move(p,Integer.parseInt(a[1]));}case "regen"->{if(a.length>1)fights.regenerate(p,Integer.parseInt(a[1]));else fights.regenerateNearby(p);}case "list"->fights.list(p);case "housebalance"->fights.showHouseBalance(p);case "housewithdraw"->fights.withdrawHouseBalance(p,a[1]);case "holo"->fights.setHologram(p,Integer.parseInt(a[1]),a.length>2&&a[2].equalsIgnoreCase("reset"));case "set"->{if(a.length<3){help(p);break;}boolean global=a[1].equalsIgnoreCase("global");if(global&&a.length<4){help(p);break;}String rawPath=global?a[2]:a[1];String value=global?a[3]:a[2];String path=rawPath.startsWith("fights.")?rawPath:"fights."+rawPath;fights.setConfigValue(p,path,value);}default->help(p);}}catch(NumberFormatException|ArrayIndexOutOfBoundsException ex){help(p);}return true;}private void help(Player p){p.sendMessage(fights.colorize("&6/fightadmin create [odd-size] [fighters], fighters <arena#> <2-16>, remove <#>, regen [#], list, housebalance, housewithdraw <amount|all>, holo <#> [reset], set <path> <value>"));}}